// See README.md for license details.
// =============================================================================
//  VALUProgrammableLutSpec.scala — tests for the programmable two-bank LUT
//
//  Covers:
//    1. vsetlut loads a 256-byte table (in K×4-byte segments) into bank A or B.
//    2. vlut performs a bit-exact per-lane lookup from the loaded bank.
//    3. Both banks are independent: bank A and B can hold different tables.
//    4. Legacy activation functions (exp, recip, tanh, erf) are verified by
//       loading the Qfmt reference tables at test time.
//
//  vsetlut protocol (VALU-direct, bypassing the backend RF):
//    - Poke in_a_vr[lane k] with the 32-bit word containing 4 table bytes:
//        bits [8*(b+1)-1 : 8*b] = table[seg*K*4 + k*4 + b]  for b in 0..3
//    - Poke ctrl with op=vsetlut, regCls=VR, round[0]=bank, imm=segment.
//    - Step 1 clock.  The banks are updated on the rising edge.
//    - Repeat for all ceil(256/(K*4)) segments.
//
//  After loading, vlut is tested by poking in_a_vx[lane] = raw LUT index (0..255)
//  and checking out_vx[lane] == table[index] after 1 clock step.
// =============================================================================

package alu.vec

import chisel3._
import chisel3.simulator.EphemeralSimulator._
import org.scalatest.flatspec.AnyFlatSpec
import isa.micro_op._

class VALUProgrammableLutSpec extends AnyFlatSpec {
  val N = 8; val K = 8
  val BANK_A = 0; val BANK_B = 1

  // ---------------------------------------------------------------------------
  // VALU ctrl helpers
  // ---------------------------------------------------------------------------

  def zeroInputs(dut: VALU): Unit = {
    for (i <- 0 until K) {
      dut.io.in_a_vx(i).poke(0.U); dut.io.in_b_vx(i).poke(0.U)
      dut.io.in_a_ve(i).poke(0.U); dut.io.in_b_ve(i).poke(0.U)
      dut.io.in_a_vr(i).poke(0.U); dut.io.in_b_vr(i).poke(0.U); dut.io.in_c_vr(i).poke(0.U)
    }
  }

  def pokeCtrl(dut: VALU, op: VecOp.Type, regCls: Int = 0,
               bank: Int = 0, imm: Int = 0): Unit = {
    dut.io.ctrl.op.poke(op)
    dut.io.ctrl.regCls.poke(regCls.U)
    dut.io.ctrl.dtype.poke(VecDType.S8C4)
    dut.io.ctrl.saturate.poke(false.B)
    dut.io.ctrl.round.poke(bank.U)   // round[0] = bank select
    dut.io.ctrl.rs3_idx.poke(0.U)
    dut.io.ctrl.imm.poke(imm.S)
  }

  // ---------------------------------------------------------------------------
  // loadBank: write a full 256-byte table into bank A or B via vsetlut.
  //
  // Segment packing at K=8:  256 / (K×4) = 8 segments.
  //   in_a_vr[k] = { table[s×K×4 + k×4 + 3],
  //                  table[s×K×4 + k×4 + 2],
  //                  table[s×K×4 + k×4 + 1],
  //                  table[s×K×4 + k×4 + 0] }   (little-endian byte order)
  // ---------------------------------------------------------------------------
  def loadBank(dut: VALU, table: Seq[Int], bank: Int): Unit = {
    val segs = 256 / (K * 4)
    for (seg <- 0 until segs) {
      zeroInputs(dut)
      for (k <- 0 until K) {
        var word = 0L
        for (b <- 0 until 4) {
          val entry = table(seg * K * 4 + k * 4 + b) & 0xFF
          word |= entry.toLong << (8 * b)
        }
        dut.io.in_a_vr(k).poke(word.U)
      }
      pokeCtrl(dut, VecOp.vsetlut, regCls = 2 /* VR */, bank = bank, imm = seg)
      dut.clock.step()
    }
  }

  // ---------------------------------------------------------------------------
  // sweepLut: verify all 256 entries of a loaded bank via vlut.
  // ---------------------------------------------------------------------------
  def sweepLut(dut: VALU, table: Seq[Int], bank: Int, label: String): Unit = {
    pokeCtrl(dut, VecOp.vlut, regCls = 0 /* VX */, bank = bank)
    for (base <- 0 until 256 by K) {
      zeroInputs(dut)
      for (i <- 0 until K) {
        dut.io.in_a_vx(i).poke(((base + i) & 0xFF).U)
      }
      dut.clock.step()
      for (i <- 0 until K) {
        val idx = (base + i) & 0xFF
        val exp = table(idx) & 0xFF
        dut.io.out_vx(i).expect(exp.U,
          s"$label bank${if (bank==0) "A" else "B"} LUT[$idx]: expected $exp")
      }
    }
  }

  // ---- Sub-case helpers ------------------------------------------------------

  // 1: Load exp into bank A and verify
  private def runExpBankA(dut: VALU): Unit = {
    loadBank(dut, Qfmt.lutExp, BANK_A)
    sweepLut(dut, Qfmt.lutExp, BANK_A, "vexp")
  }

  // 2: Load recip into bank B and verify
  private def runRecipBankB(dut: VALU): Unit = {
    loadBank(dut, Qfmt.lutRecip, BANK_B)
    sweepLut(dut, Qfmt.lutRecip, BANK_B, "vrecip")
  }

  // 3: Load tanh into A and erf into B; verify both
  private def runTwoBanks(dut: VALU): Unit = {
    loadBank(dut, Qfmt.lutTanh, BANK_A)
    loadBank(dut, Qfmt.lutErf,  BANK_B)
    sweepLut(dut, Qfmt.lutTanh, BANK_A, "vtanh")
    sweepLut(dut, Qfmt.lutErf,  BANK_B, "verf")
  }

  // 4: Overwrite bank A
  private def runOverwriteBankA(dut: VALU): Unit = {
    // Load exp first, then overwrite with recip
    loadBank(dut, Qfmt.lutExp,   BANK_A)
    loadBank(dut, Qfmt.lutRecip, BANK_A)
    // Only recip should be visible now
    sweepLut(dut, Qfmt.lutRecip, BANK_A, "overwrite-recip")
  }

  // 5: recip(0) sentinel via vlut
  private def runRecipZeroSentinel(dut: VALU): Unit = {
    loadBank(dut, Qfmt.lutRecip, BANK_A)
    pokeCtrl(dut, VecOp.vlut, regCls = 0, bank = BANK_A)
    zeroInputs(dut)
    // all lanes index 0 → recip(0) = sentinel 127
    for (i <- 0 until K) dut.io.in_a_vx(i).poke(0.U)
    dut.clock.step()
    for (i <- 0 until K)
      dut.io.out_vx(i).expect(127.U, s"vlut recip(0) sentinel lane $i")
  }

  // 8: Compiler-defined identity table
  private def runIdentityTable(dut: VALU): Unit = {
    val identityTable = (0 until 256).map(_ & 0xFF)
    loadBank(dut, identityTable, BANK_A)
    sweepLut(dut, identityTable, BANK_A, "identity")
  }

  // ---- Coalesced simulate-based test ----------------------------------------

  "VALU vlut/vsetlut" should "pass all programmable-LUT sub-cases" in {
    simulate(new VALU(K, N)) { dut =>
      withClue("exp bank A: ")            { runExpBankA(dut)           }
      withClue("recip bank B: ")          { runRecipBankB(dut)         }
      withClue("two banks (tanh+erf): ")  { runTwoBanks(dut)           }
      withClue("overwrite bank A: ")      { runOverwriteBankA(dut)     }
      withClue("recip(0) sentinel: ")     { runRecipZeroSentinel(dut)  }
      withClue("identity table: ")        { runIdentityTable(dut)      }
    }
  }

  // ---- Pure-Scala property tests (no DUT, kept separate) --------------------

  // 6: Legacy property — vexp has no zero entries in the Qfmt table
  "VALU vlut/vsetlut" should "have no zero entries in the Qfmt exp table" in {
    for (raw <- 0 until 256)
      assert(Qfmt.lutExp(raw) != 0, s"Qfmt.lutExp[$raw] = 0")
  }

  // 7: Legacy property — Qfmt tanh table is monotone non-decreasing
  "VALU vlut/vsetlut" should "have a monotone non-decreasing Qfmt tanh table" in {
    var prev = Qfmt.lutTanh(128)
    val order = (-128 until 128).map(v => if (v < 0) v + 256 else v)
    for (raw <- order) {
      val cur  = Qfmt.lutTanh(raw)
      val curS  = if (cur  >= 128) cur  - 256 else cur
      val prevS = if (prev >= 128) prev - 256 else prev
      assert(curS >= prevS - 1,
        s"Qfmt.lutTanh not monotone at raw=$raw: prev=$prevS cur=$curS")
      prev = cur
    }
  }
}

// See README.md for license details.
// Softmax and GELU composition tests using VALU primitives.
//
// LUT-based activation functions (exp, erf) are loaded into the VALU's
// programmable banks via vsetlut before each test

package alu.vec

import scala.util.Random
import chisel3._
import chisel3.simulator.EphemeralSimulator._
import org.scalatest.flatspec.AnyFlatSpec
import isa.micro_op._

class VALUActivationSpec extends AnyFlatSpec {
  val N = 8; val K = 8
  val WX = 0; val WE = 1; val WR = 2
  val BANK_A = 0; val BANK_B = 1

  def pokeCtrl(dut: VALU, op: VecOp.Type, width: Int = WX,
               sat: Boolean = false, bank: Int = 0, imm: Int = 0): Unit = {
    dut.io.ctrl.op.poke(op); dut.io.ctrl.regCls.poke(width.U)
    dut.io.ctrl.dtype.poke(VecDType.S8C4); dut.io.ctrl.saturate.poke(sat.B)
    dut.io.ctrl.round.poke(bank.U)  // round[0] = bank select for vlut/vsetlut
    dut.io.ctrl.rs3_idx.poke(0.U); dut.io.ctrl.imm.poke(imm.S)
  }

  def pokeVX(dut: VALU, a: Array[Int], b: Array[Int] = Array.fill(8)(0)): Unit = {
    for (i <- 0 until K) {
      dut.io.in_a_vx(i).poke((a(i) & 0xFF).U); dut.io.in_b_vx(i).poke((b(i) & 0xFF).U)
      dut.io.in_a_ve(i).poke(0.U); dut.io.in_b_ve(i).poke(0.U)
      dut.io.in_a_vr(i).poke(0.U); dut.io.in_b_vr(i).poke(0.U); dut.io.in_c_vr(i).poke(0.U)
    }
  }

  def readVX(dut: VALU): Array[Int] = Array.tabulate(K)(i => dut.io.out_vx(i).peek().litValue.toInt)
  def readVR(dut: VALU): Array[Long] = Array.tabulate(K)(i => dut.io.out_vr(i).peek().litValue.toLong)

  /** Load a 256-byte table into the given bank via vsetlut. */
  def loadBank(dut: VALU, table: Seq[Int], bank: Int): Unit = {
    val segs = 256 / (K * 4)
    for (seg <- 0 until segs) {
      for (i <- 0 until K) {
        dut.io.in_a_vx(i).poke(0.U); dut.io.in_b_vx(i).poke(0.U)
        dut.io.in_a_ve(i).poke(0.U); dut.io.in_b_ve(i).poke(0.U)
        dut.io.in_c_vr(i).poke(0.U); dut.io.in_b_vr(i).poke(0.U)
        var word = 0L
        for (b <- 0 until 4) {
          val entry = table(seg * K * 4 + i * 4 + b) & 0xFF
          word |= entry.toLong << (8 * b)
        }
        dut.io.in_a_vr(i).poke(word.U)
      }
      pokeCtrl(dut, VecOp.vsetlut, width = WR, bank = bank, imm = seg)
      dut.clock.step()
    }
  }

  // ---- Sub-case helpers ------------------------------------------------------

  private def runSoftmax(dut: VALU): Unit = {
    val rand = new Random(0x5AFE)
    // Load exp into bank A and recip into bank B once before the loop.
    loadBank(dut, Qfmt.lutExp,   BANK_A)
    loadBank(dut, Qfmt.lutRecip, BANK_B)

    for (_ <- 0 until 16) {
      val xRaw = Array.fill(K)(rand.between(-128, 128))

      // Step 1: vrmax
      pokeCtrl(dut, VecOp.vrmax)
      pokeVX(dut, xRaw)
      dut.clock.step()
      val maxVal = dut.io.out_vr(0).peek().litValue.toInt

      // Step 2: vsub (x - max)
      pokeCtrl(dut, VecOp.vsub, sat = true)
      pokeVX(dut, xRaw, Array.fill(K)(maxVal))
      dut.clock.step()
      val xShifted = readVX(dut)

      // Step 3: vlut bank A (exp)
      pokeCtrl(dut, VecOp.vlut, bank = BANK_A)
      pokeVX(dut, xShifted)
      dut.clock.step()
      val eVec = readVX(dut)

      // Step 4: vsum
      pokeCtrl(dut, VecOp.vsum)
      pokeVX(dut, eVec)
      dut.clock.step()
      val sumEHwU = dut.io.out_vr(0).peek().litValue.toLong & 0xFFFFFFFFL
      val sumEHw = sumEHwU.toInt.toLong
      val expectedSumSigned = eVec.map(v => (v & 0xFF).toByte.toLong).sum
      assert(Math.abs(sumEHw - expectedSumSigned) <= K,
        s"vsum mismatch: hw=$sumEHw sw=$expectedSumSigned")

      // Step 5: vlut bank B (recip), clamped sum
      val sumSq16 = math.max(1, math.min(127, sumEHw.toInt))
      pokeCtrl(dut, VecOp.vlut, bank = BANK_B)
      pokeVX(dut, Array.fill(K)(sumSq16))
      dut.clock.step()
      val recipSum = readVX(dut)
      for (r <- recipSum) assert(r >= 0, s"recip should be non-negative, got $r")

      // Step 6: vmul (e * recip)
      pokeCtrl(dut, VecOp.vmul, sat = false)
      pokeVX(dut, eVec, recipSum)
      dut.clock.step()

      // Scala reference: softmax probabilities sum to 1.0
      val xD = xRaw.map(Qfmt.sq16ToDouble)
      val maxD = xD.max
      val expD = xD.map(x => math.exp(x - maxD))
      val sumD = expD.sum
      val probsD = expD.map(_ / sumD)
      assert(Math.abs(probsD.sum - 1.0) < 0.01, s"reference softmax sum=${probsD.sum}")
    }
  }

  private def runGelu(dut: VALU): Unit = {
    val rand = new Random(0x6E10)
    // Load erf table into bank A for GELU approximation
    // (overwrites whatever bank A held from the previous sub-case).
    loadBank(dut, Qfmt.lutErf, BANK_A)

    for (_ <- 0 until 16) {
      val posIn = Array.fill(K)(rand.between(1, 64))
      val negIn = Array.fill(K)(rand.between(-64, -1))

      def runOne(xRaw: Array[Int]): Array[Int] = {
        pokeCtrl(dut, VecOp.vsra)
        pokeVX(dut, xRaw, Array.fill(K)(1))
        dut.clock.step()
        val xHalf = readVX(dut)

        // vlut bank A (erf)
        pokeCtrl(dut, VecOp.vlut, bank = BANK_A)
        pokeVX(dut, xHalf)
        dut.clock.step()
        val e = readVX(dut)

        pokeCtrl(dut, VecOp.vadd, sat = true)
        pokeVX(dut, e, Array.fill(K)(64))
        dut.clock.step()
        val e1 = readVX(dut)

        pokeCtrl(dut, VecOp.vmul, sat = false)
        pokeVX(dut, xRaw, e1)
        dut.clock.step()
        val prodWide = readVR(dut)
        prodWide.map(p => (p >> 7).toInt)
      }

      val posGelu = runOne(posIn)
      val negGelu = runOne(negIn)

      posGelu.zipWithIndex.foreach { case (g, i) =>
        assert(g >= 0, f"GELU(pos) lane $i input=${Qfmt.sq16ToDouble(posIn(i) & 0xFF)}%.3f gelu=$g")
      }
      val strongNeg = negIn.map(_ < -32)
      negGelu.zipWithIndex.foreach { case (g, i) =>
        if (strongNeg(i))
          assert(g <= 0, f"GELU(neg) lane $i input=${Qfmt.sq16ToDouble(negIn(i) & 0xFF)}%.3f gelu=$g")
      }
    }
  }

  // ---- Coalesced test --------------------------------------------------------

  "VALU activation" should "pass softmax and GELU composition sub-cases" in {
    simulate(new VALU(K, N)) { dut =>
      withClue("softmax: ") { runSoftmax(dut) }
      withClue("GELU: ")    { runGelu(dut)    }
    }
  }
}

